#!/usr/bin/env bash
# Reproduce the hidden-test result for task 'invoice_report' against the code agent.py
# shipped (in ./src). Regenerated by eval.py on every run.
set -u
here="$(cd "$(dirname "$0")" && pwd)"
work="$(mktemp -d)"
mkdir -p "$work/src" "$work/tests"
cp -r "$here/src/." "$work/src/" 2>/dev/null || true
cp -r "/home/student_00_942290e85106/tasks/invoice_report/tests/." "$work/tests/"
( cd "$work" && /home/student_00_942290e85106/.venv/bin/python tests/hidden.py ); code=$?
echo "hidden.py exit code: $code (0 = PASS)"
rm -rf "$work"
exit $code
